ax.set_yticks(y); ax.set_yticklabels([r[0] for r in ROWS], fontsize=8.5); ax.set_xticks([x + 0.5 for x in xo]); ax.set_xticklabels(["all 80 days", "winter (30)", "summer (50)"]); ax.tick_params(length=0); ax.set_xlim(0, 4.5); [ax.spines[s].set_visible(False) for s in ("top", "right", "bottom")]; ax.set_xlabel("whole-day MAE, ct/kWh (bars to one scale)")
