ax = axs[1]; CMP = (("PRIMARY: average(A, P) minus P", E["B"] - E["P"], AQUA), ("control: average of two price runs minus P", E["C"] - E["P"], NEUT), ("average(A, P) minus the control average", E["B"] - E["C"], BLUE), ("A minus P, whole day", E["A"] - E["P"], BLUE), ("A minus P, night 00-06", S["night_A"] - S["night_P"], BLUE)); y = np.arange(len(CMP))[::-1]
for yy, (lab, d, col) in zip(y, CMP): lo, hi = boot(d); ax.hlines(yy, lo, hi, color=col, linewidth=2.6); ax.plot(d.mean(), yy, "o", color=col, markersize=7); ax.text(hi + 0.006, yy - 0.06, f"{d.mean():+.3f}", fontsize=8.5, color=INK)
ax.axvline(0, color=INK, linewidth=0.7); ax.set_yticks(y); ax.set_yticklabels([c[0] for c in CMP], fontsize=8.5); ax.set_xlabel("paired difference in MAE, ct/kWh (dot: mean, bar: 5-95% block bootstrap)"); ax.grid(True, axis="x", color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; ax.set_xlim(-0.14, 0.09)
