ax = axs[2]; pl = {k: S[f"pin_{k}"] for k in ("QA", "QP", "QV")}; x = np.arange(3); v = [pl[k].mean() for k in ("QA", "QP", "QV")]; ax.bar(x, v, 0.6, color=[BLUE, ORANGE, AQUA], linewidth=0)
for i, (val, cov) in enumerate(zip(v, (0.929, 0.885, 0.923))): ax.text(i, val + 0.004, f"{val:.3f}", ha="center", fontsize=9, color=INK); ax.text(i, 0.02, f"90% band\ncovers\n{cov:.0%}", ha="center", fontsize=8.5, color=SURF, fontweight="bold")
ax.set_xticks(x); ax.set_xticklabels(["market model\n(shift + load uncertainty)", "price route", "quantile average"], fontsize=8.5); ax.set_ylabel("mean pinball loss over five quantile levels, whole day"); ax.set_ylim(0, 0.32); ax.grid(True, axis="y", color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; d = pl["QV"] - pl["QP"]; b = boot(d)
ttl(ax, f"Distributions: the quantile average is {-100 * d.mean() / pl['QP'].mean():.0f}% better than\nthe price route ({100 * b[0] / pl['QP'].mean():+.0f}% .. {100 * b[1] / pl['QP'].mean():+.0f}%)")
